import{_ as n,C as i,o as s,c as d,j as r,a,E as o,al as l}from"./chunks/framework.7vp1BMOE.js";const v=JSON.parse('{"title":"Terabee TeraRanger Rangefinders (Discontinued)","description":"","frontmatter":{},"headers":[],"relativePath":"ko/sensor/teraranger.md","filePath":"ko/sensor/teraranger.md"}'),h={name:"ko/sensor/teraranger.md"};function p(c,e,u,g,f,m){const t=i("Badge");return s(),d("div",null,[e[0]||(e[0]=r("h1",{id:"terabee-teraranger-rangefinders-discontinued",tabindex:"-1"},[a("Terabee TeraRanger Rangefinders (Discontinued) "),r("a",{class:"header-anchor",href:"#terabee-teraranger-rangefinders-discontinued","aria-label":'Permalink to "Terabee TeraRanger Rangefinders (Discontinued)"'},"​")],-1)),o(t,{type:"tip",text:"PX4 v1.0"}),e[1]||(e[1]=a()),o(t,{type:"info",text:"Discontinued"}),e[2]||(e[2]=l('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>TeraRanger Evo sensors were discontinued by Terabee in May 2024. Limited stock may still be available from third-party resellers (see <a href="#store">Where to Buy</a>).</p></div><p>Terabee TeraRanger sensors are small, lightweight <a href="./../sensor/rangefinders">rangefinders</a> based on infrared Time-of-Flight (ToF) technology, with maximum ranges from 3 m to 60 m (depending on the model). They connect to the flight controller using I2C.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The driver for these rangefinders is not included in PX4 firmware by default. See <a href="#firmware_support">Firmware Support</a> for how to add it.</p></div><h2 id="supported_models" tabindex="-1">Supported Models <a class="header-anchor" href="#supported_models" aria-label="Permalink to &quot;Supported Models {#supported_models}&quot;">​</a></h2><p>PX4 supports the following models.</p><table tabindex="0"><thead><tr><th>모델</th><th>범위</th><th>Current draw</th><th><a href="./../advanced_config/parameter_reference#SENS_EN_TRANGER">SENS_EN_TRANGER</a></th><th>참고</th></tr></thead><tbody><tr><td>TeraRanger Evo 60m</td><td>0.5–60 m</td><td>90–330 mA</td><td><code>3</code></td><td>Requires the Evo I2C/UART backboard.</td></tr><tr><td>TeraRanger Evo 600Hz</td><td>0.75–8 m</td><td>95–190 mA</td><td><code>4</code></td><td>Requires the Evo I2C/UART backboard.</td></tr><tr><td>TeraRanger Evo 3m</td><td>0.1–3 m</td><td>70–250 mA</td><td><code>5</code></td><td>Requires the Evo I2C/UART backboard.</td></tr><tr><td>TeraRanger One</td><td>0.2–14 m</td><td></td><td><code>2</code></td><td></td></tr></tbody></table><h2 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications {#specifications}&quot;">​</a></h2><p>The following specifications apply to TeraRanger Evo sensors fitted with the Evo I2C/UART backboard.</p><ul><li><strong>Technology:</strong> Infrared Time-of-Flight (LED)</li><li><strong>Field of view:</strong> Approx. 2° (Evo 60m)</li><li><strong>Interface:</strong> I2C (3.3 V logic, address <code>0x31</code>)</li><li><strong>Input voltage:</strong> 5 V DC ±5%</li><li><strong>Dimensions:</strong> Approx. 29 x 29 x 22 mm (sensor and backboard)</li><li><strong>Weight:</strong> 9 g (sensor) + 3 g (backboard)</li></ul><h2 id="store" tabindex="-1">Where to Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where to Buy {#store}&quot;">​</a></h2><p>TeraRanger sensors are no longer sold by Terabee. At the time of writing the following are still listed by the reseller Tribotix:</p><ul><li><a href="https://tribotix.com/product/teraranger-evo-60m/" target="_blank" rel="noreferrer">TeraRanger Evo 60m</a></li><li><a href="https://tribotix.com/product/teraranger-evo-600hz/" target="_blank" rel="noreferrer">TeraRanger Evo 600Hz</a></li><li><a href="https://tribotix.com/product/teraranger-evo-3m/" target="_blank" rel="noreferrer">TeraRanger Evo 3m</a></li></ul><p>Select the <strong>I2C/UART</strong> interface option when ordering (PX4 cannot use the USB backboard).</p><h2 id="hardware_setup" tabindex="-1">Hardware Setup <a class="header-anchor" href="#hardware_setup" aria-label="Permalink to &quot;Hardware Setup {#hardware_setup}&quot;">​</a></h2><h3 id="mounting" tabindex="-1">Mounting <a class="header-anchor" href="#mounting" aria-label="Permalink to &quot;Mounting {#mounting}&quot;">​</a></h3><p>PX4 assumes that the sensor is facing down (the orientation cannot be configured).</p><p>For TeraRanger Evo sensors:</p><ul><li>Do not mount anything directly in front of the sensor, or within a cone of approximately ±15° around its optical axis.</li><li>Within the first metre, avoid highly reflective objects within a cone of approximately ±45° around the optical axis.</li><li>Do not add a cover in front of the sensor.</li><li>Rotor blades in the field of view can affect the readings.</li></ul><h3 id="pinouts" tabindex="-1">Pinouts <a class="header-anchor" href="#pinouts" aria-label="Permalink to &quot;Pinouts {#pinouts}&quot;">​</a></h3><p>TeraRanger Evo sensors must be fitted with the Evo I2C/UART backboard, which has a single 9-pin Hirose DF13 connector.</p><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>설명</th></tr></thead><tbody><tr><td>1</td><td>Tx</td><td>UART transmit (3.3 V logic)</td></tr><tr><td>2</td><td>Rx</td><td>UART receive (3.3 V logic)</td></tr><tr><td>3</td><td>GND</td><td>접지</td></tr><tr><td>4</td><td>SDA</td><td>I2C data (3.3 V logic)</td></tr><tr><td>5</td><td>SCL</td><td>I2C clock (3.3 V logic)</td></tr><tr><td>6</td><td>-</td><td>Reserved</td></tr><tr><td>7</td><td>5V</td><td>+5 V supply input</td></tr><tr><td>8</td><td>GND</td><td>접지</td></tr><tr><td>9</td><td>-</td><td>Reserved</td></tr></tbody></table><h3 id="wiring" tabindex="-1">Wiring <a class="header-anchor" href="#wiring" aria-label="Permalink to &quot;Wiring {#wiring}&quot;">​</a></h3><p>All TeraRanger sensors must be connected via the I2C bus, using an external <code>I2C</code> port on the flight controller.</p><table tabindex="0"><thead><tr><th>Backboard pin</th><th>Connect to</th></tr></thead><tbody><tr><td>4 (SDA)</td><td>Flight controller I2C SDA</td></tr><tr><td>5 (SCL)</td><td>Flight controller I2C SCL</td></tr><tr><td>7 (5V)</td><td>5 V DC supply</td></tr><tr><td>3 or 8 (GND)</td><td>Flight controller GND</td></tr></tbody></table><p>The UART pins are not used by PX4.</p><p>The sensor requires a 5 V DC (±5%) supply, and can draw up to 330 mA depending on the <a href="#supported_models">supported model</a>. Check that the flight controller port can supply this, or power the sensor from a separate supply that shares a ground with the flight controller.</p><p>The backboard has built-in 10 kΩ pull-up resistors on SDA and SCL, so do not add further pull-ups on the same bus. The sensor must be left at its default I2C address (<code>0x31</code>).</p><h2 id="firmware_support" tabindex="-1">Firmware Support <a class="header-anchor" href="#firmware_support" aria-label="Permalink to &quot;Firmware Support {#firmware_support}&quot;">​</a></h2><p>The rangefinder is supported by the <a href="./../modules/modules_driver_distance_sensor#teraranger">teraranger</a> driver, which is built into firmware by the <a href="./../hardware/porting_guide_config">board configuration</a> key <code>CONFIG_DRIVERS_DISTANCE_SENSOR_TERARANGER=y</code>.</p><p>The driver is not part of the common set of rangefinder drivers (<code>CONFIG_COMMON_DISTANCE_SENSOR</code>), so it is only present in the firmware for boards that set that key.</p><p>To check your board, look for the key in its configuration file, <code>boards/&lt;vendor&gt;/&lt;board&gt;/default.px4board</code>, or check whether <a href="./../advanced_config/parameter_reference#SENS_EN_TRANGER">SENS_EN_TRANGER</a> is listed in <em>QGroundControl</em> (parameters are only shown for drivers that are in the firmware).</p><p>To add the driver, add the key to the board&#39;s <code>default.px4board</code> file, or enable it in <a href="./../hardware/porting_guide_config#px4-menuconfig-setup">boardconfig</a> under <strong>Drivers &gt; Distance sensors</strong>, and then <a href="./../dev_setup/building_px4">build and upload the firmware</a>.</p><p>The driver does not start until it is enabled using the parameter in <a href="#px4_configuration">PX4 Configuration</a>.</p><h2 id="px4_configuration" tabindex="-1">PX4 Configuration <a class="header-anchor" href="#px4_configuration" aria-label="Permalink to &quot;PX4 Configuration {#px4_configuration}&quot;">​</a></h2><p>Set <a href="./../advanced_config/parameter_reference#SENS_EN_TRANGER">SENS_EN_TRANGER</a> to the value for your sensor in the <a href="#supported_models">Supported Models</a> table, and then reboot.</p><p>You can instead set the parameter to <code>1</code> to have PX4 detect the sensor.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If using auto-detect for Evo sensors the minimum and maximum values for the range are set to the lowest and highest possible readings across the Evo family (currently 0.1–60 m). 올바른 최대/최소 값을 사용하려면 Evo 센서의 적절한 모델을 매개변수에 설정합니다 (자동 감지를 사용하는 대신).</p></div><p>If the parameter is not available in <em>QGroundControl</em> then the driver is not in the firmware: see <a href="#firmware_support">Firmware Support</a>.</p><p>The configuration that is common to all rangefinders, such as the sensor position offsets used by the estimator, is covered in <a href="./../sensor/rangefinders#configuration">Rangefinders &gt; Configuration/Setup</a>.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing {#testing}&quot;">​</a></h2><p>You can check that the driver is running, and see its error counters, using the <em>QGroundControl MAVLink Console</em>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">teraranger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>You can observe the published measurements with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">listener</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> distance_sensor</span></span></code></pre></div><p>The measurements can also be viewed in the <code>DISTANCE_SENSOR</code> message in the <em>QGroundControl MAVLink Inspector</em>. For more information see <a href="./../sensor/rangefinders#testing">Rangefinders &gt; Testing</a>.</p><h2 id="further_information" tabindex="-1">Further Information <a class="header-anchor" href="#further_information" aria-label="Permalink to &quot;Further Information {#further_information}&quot;">​</a></h2><ul><li><a href="./../modules/modules_driver_distance_sensor#teraranger">Modules Reference: Distance Sensor (Driver): teraranger</a></li><li><a href="https://web.archive.org/web/20240611084754/http://www.terabee.com/wp-content/uploads/2021/02/User-Manual-for-TeraRanger-Evo-single-point-distance-sensors-and-backboards.pdf" target="_blank" rel="noreferrer">User Manual for TeraRanger Evo single point distance sensors and backboards</a> (Terabee, archived copy)</li><li><a href="https://acroname.com/sites/default/files/assets/teraranger-evo-specification-sheet.pdf" target="_blank" rel="noreferrer">TeraRanger Evo Specification Sheet</a> (Terabee, hosted by Acroname)</li></ul>',47))])}const _=n(h,[["render",p]]);export{v as __pageData,_ as default};
